<template><view class="mc-page"><view class="hero"><view><text class="hero-kicker">MEMBER SERVICE</text><text class="hero-title">会员服务卡</text><text class="hero-sub">开卡、收款、核销，店员一次操作完成</text></view><view class="hero-badge"><text>{{ overview.active_card_count||0 }}</text><small>有效卡</small></view></view><view class="quick-grid"><view class="quick primary" @click="go('/addon/hsx_member_card/pages/order/create')"><u-icon name="plus" color="#fff" size="25"/><text>快速开卡</text><small>选客户 · 选卡种 · 收款</small></view><view class="quick" @click="go('/addon/hsx_member_card/pages/card/search')"><u-icon name="phone" color="#3b6ef5" size="25"/><text>手机号核销</text><small>后四位 + 姓名核对</small></view></view><view class="section-title"><text>今日经营</text><text class="refresh" @click="load">刷新</text></view><view class="metrics"><view v-for="item in metrics" :key="item.label" class="metric"><text>{{item.label}}</text><strong :class="item.color">{{item.value}}</strong><small>{{item.help}}</small></view></view><view class="entry-list"><u-cell title="开卡订单" label="查看待收款和异常订单" isLink @click="go('/addon/hsx_member_card/pages/order/list')"><template #icon><view class="cell-icon blue"><u-icon name="order" color="#3b6ef5" size="20"/></view></template></u-cell><u-cell title="核销记录" label="查询服务人员与冲正记录" isLink @click="go('/addon/hsx_member_card/pages/redemption/list')"><template #icon><view class="cell-icon green"><u-icon name="checkmark-circle" color="#16a34a" size="20"/></view></template></u-cell></view></view></template>
<script setup lang="ts">import{computed,ref}from'vue';import{onShow}from'@dcloudio/uni-app';import{getMemberCardDashboard}from'../../api';const overview=ref<any>({}),money=(v:any)=>Number(v||0).toFixed(2);const metrics=computed(()=>[{label:'今日开卡',value:`${overview.value.issued_count||0} 张`,help:'有效开卡订单'},{label:'实际收款',value:`¥${money(overview.value.actual_received_amount)}`,help:'ERP 已确认',color:'green'},{label:'待收款',value:`¥${money(overview.value.pending_receivable_amount)}`,help:'财务待跟进',color:'orange'},{label:'今日核销',value:`${overview.value.redemption_count||0} 次`,help:`确认收入 ¥${money(overview.value.recognized_amount)}`}]);const load=async()=>{try{overview.value=((await getMemberCardDashboard())as any)?.data||{}}catch{}};const go=(url:string)=>uni.navigateTo({url});onShow(load)</script>
<style scoped>.mc-page{min-height:100vh;padding:24rpx;background:#f3f4f6;box-sizing:border-box}.hero{display:flex;min-height:220rpx;padding:32rpx;border-radius:22rpx;background:linear-gradient(135deg,#1d4ed8,#3b82f6);color:#fff;align-items:center;justify-content:space-between;box-shadow:0 16rpx 38rpx rgba(59,110,245,.2)}.hero-kicker,.hero-title,.hero-sub,.hero-badge text,.hero-badge small{display:block}.hero-kicker{font-size:20rpx;letter-spacing:3rpx;opacity:.72}.hero-title{margin-top:12rpx;font-size:42rpx;font-weight:750}.hero-sub{margin-top:12rpx;font-size:23rpx;opacity:.82}.hero-badge{min-width:116rpx;padding:22rpx 14rpx;border:1rpx solid rgba(255,255,255,.3);border-radius:18rpx;background:rgba(255,255,255,.12);text-align:center}.hero-badge text{font-size:36rpx;font-weight:750}.hero-badge small{margin-top:4rpx;font-size:20rpx}.quick-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18rpx;margin-top:22rpx}.quick{display:flex;min-height:140rpx;padding:24rpx;border:1rpx solid #e6ebf2;border-radius:18rpx;background:#fff;flex-direction:column;justify-content:center;box-sizing:border-box}.quick.primary{border-color:#3b6ef5;background:#3b6ef5;color:#fff}.quick text{margin-top:12rpx;font-size:28rpx;font-weight:700}.quick small{margin-top:5rpx;color:#94a3b8;font-size:20rpx}.quick.primary small{color:rgba(255,255,255,.72)}.section-title{display:flex;margin:30rpx 2rpx 16rpx;align-items:center;justify-content:space-between;font-size:29rpx;font-weight:700}.refresh{color:#3b6ef5;font-size:23rpx;font-weight:400}.metrics{display:grid;grid-template-columns:repeat(2,1fr);gap:1rpx;border:1rpx solid #e9edf3;border-radius:18rpx;background:#e9edf3;overflow:hidden}.metric{display:flex;min-height:130rpx;padding:20rpx;background:#fff;flex-direction:column;justify-content:space-between}.metric text,.metric small{color:#64748b;font-size:21rpx}.metric strong{font-size:31rpx}.metric strong.green{color:#16a34a}.metric strong.orange{color:#ea580c}.entry-list{margin-top:22rpx;border-radius:18rpx;background:#fff;overflow:hidden}.cell-icon{display:flex;width:62rpx;height:62rpx;margin-right:18rpx;border-radius:14rpx;align-items:center;justify-content:center}.cell-icon.blue{background:#eff6ff}.cell-icon.green{background:#f0fdf4}</style>
